import gurobipy as gp
from gurobipy import GRB
products = []
value = {}
weight = {}
capacity = None
for rec in LEGACY_RECORDS:
    src = rec['source']
    vals = rec['values']
    if src.endswith('capacity.csv'):
        if capacity is not None:
            raise ValueError('Multiple capacity records found')
        try:
            capacity = int(vals['Capacity'])
        except Exception:
            raise ValueError('Invalid capacity value')
    elif src.endswith('products.csv'):
        pname = vals['ProductName']
        try:
            v = int(vals['Value'])
            w = int(vals['Weight'])
        except Exception:
            raise ValueError(f'Invalid Value or Weight for product {pname}')
        products.append(pname)
        value[pname] = v
        weight[pname] = w
if capacity is None:
    raise ValueError('No capacity record found')
if set(value.keys()) != set(products) or set(weight.keys()) != set(products):
    raise ValueError('Mismatch in product identifiers')
m = gp.Model('SupermarketOrder')
m.Params.MIPGap = 0.0001
x_vars = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[p] * x_vars[p] for p in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[p] * x_vars[p] for p in products)) <= capacity, name='capacity')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in x_vars.values():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')